SELECT task_code, task_name, task_type, enabled, active_revision_id, draft_revision_id, config_version
FROM int_integration_task
WHERE task_code = #{taskCode}

SELECT revision_id, task_code, revision_no, status, config_json, config_checksum, dependency_revisions_json
FROM int_integration_task_revision
WHERE revision_id = #{revisionId}
